SELECT ?n ?point ?tsid WHERE {
  ?point a brick:ElectricPowerSensor .
  ?point brick:measuredLocation ?z .
  ?z brick:hasName ?n .
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?z ?where ?point WHERE {
  ?point a brick:ElectricPowerSensor .
  OPTIONAL { ?point ?p ?o } .
  FILTER(?o IN ("Lighting","lighting"))
}

SELECT ?z ?n WHERE {
  ?p a brick:Electric_Power_Sensor ;
     brick:isPointOf ?z .
  ?z a ?zc .
  OPTIONAL { ?z brick:hasName ?n } .
}

SELECT ?e ?s ?o WHERE {
  ?e ?s ?o .
  FILTER(CONTAINS(str(?o), "Zone") OR CONTAINS(str(?e), "Zone") OR CONTAINS(str(?o), "Per") OR CONTAINS(str(?o), "core") OR CONTAINS(str(?e), "core"))
  FILTER(?s = ref:ifcReference OR ?s = ref:IFCReference OR CONTAINS(str(?s),"IFC") OR CONTAINS(str(?s),"ifc"))
} LIMIT 100

